/**
 * Popover Component
 *
 * A fully accessible popover component for richer interactive content.
 * Uses Floating UI for intelligent positioning.
 *
 * @example
 * ```tsx
 * import { Popover, PopoverHeader, PopoverBody } from '@dsai-io/react';
 *
 * <Popover header="Settings" content="Configure your preferences.">
 *   <button>Open Settings</button>
 * </Popover>
 * ```
 */

// Main component
export { Popover } from './Popover';
// FSM exports
export {
  createInitialPopoverFSMState,
  getPopoverVisualState,
  popoverFSMReducer,
} from './Popover.fsm';
// Types
export type {
  PopoverBodyProps,
  PopoverCloseButtonProps,
  PopoverContextValue,
  PopoverFSMEvent,
  PopoverFSMState,
  PopoverHeaderProps,
  PopoverPlacement,
  PopoverProps,
  PopoverTrigger,
  PopoverVisualState,
  SafePopoverHTMLAttributes,
} from './Popover.types';
// Subcomponents
export { PopoverBody } from './PopoverBody';
export { PopoverCloseButton } from './PopoverCloseButton';
export { PopoverHeader } from './PopoverHeader';

import type { PopoverFSMEvent, PopoverFSMState, PopoverVisualState } from './Popover.types';

/**
 * Creates the initial Popover FSM state
 *
 * @param defaultOpen - Whether the popover should start open
 * @returns Initial FSM state
 *
 * @example
 * ```ts
 * const initialState = createInitialPopoverFSMState(false);
 * ```
 */
export function createInitialPopoverFSMState(defaultOpen = false): PopoverFSMState {
  if (defaultOpen) {
    return {
      visibility: 'open',
      shouldRender: true,
    };
  }
  return {
    visibility: 'closed',
    shouldRender: false,
  };
}

/**
 * Popover FSM reducer
 *
 * Handles all popover visibility state transitions:
 * - OPEN: Transition to opening/open state
 * - CLOSE: Transition to closing/closed state
 * - ANIMATION_END: Complete transition after animation
 *
 * State machine:
 * ```
 * closed -> (OPEN) -> opening -> (ANIMATION_END) -> open
 * open -> (CLOSE) -> closing -> (ANIMATION_END) -> closed
 * ```
 *
 * @param state - Current FSM state
 * @param event - FSM event to process
 * @returns Updated FSM state
 *
 * @example
 * ```ts
 * const [state, dispatch] = useReducer(popoverFSMReducer, createInitialPopoverFSMState());
 * dispatch({ type: 'OPEN' });
 * ```
 */
export function popoverFSMReducer(state: PopoverFSMState, event: PopoverFSMEvent): PopoverFSMState {
  switch (event.type) {
    case 'OPEN': {
      if (state.visibility === 'closed' || state.visibility === 'closing') {
        return {
          visibility: 'opening',
          shouldRender: true,
        };
      }
      return state;
    }

    case 'CLOSE': {
      if (state.visibility === 'open' || state.visibility === 'opening') {
        return {
          visibility: 'closing',
          shouldRender: true,
        };
      }
      return state;
    }

    case 'ANIMATION_END': {
      if (state.visibility === 'opening') {
        return {
          visibility: 'open',
          shouldRender: true,
        };
      }
      if (state.visibility === 'closing') {
        return {
          visibility: 'closed',
          shouldRender: false,
        };
      }
      return state;
    }

    default:
      return state;
  }
}

/**
 * Get the visual state attribute value for the popover
 *
 * @param state - Current FSM state
 * @returns Visual state string for data-visual-state attribute
 *
 * @example
 * ```ts
 * const visualState = getPopoverVisualState(fsmState);
 * <div data-visual-state={visualState} />
 * ```
 */
export function getPopoverVisualState(state: PopoverFSMState): PopoverVisualState {
  switch (state.visibility) {
    case 'closed':
      return 'hidden';
    case 'opening':
      return 'showing';
    case 'open':
      return 'visible';
    case 'closing':
      return 'hiding';
  }
}

import {
  arrow,
  autoUpdate,
  flip,
  FloatingArrow,
  FloatingFocusManager,
  FloatingPortal,
  offset,
  shift,
  useClick,
  useDismiss,
  useFloating,
  useFocus,
  useHover,
  useInteractions,
  useRole,
  useTransitionStyles,
} from '@floating-ui/react';
import {
  cloneElement,
  forwardRef,
  useCallback,
  useEffect,
  useId,
  useMemo,
  useReducer,
  useState,
} from 'react';

import { cn } from '../../utils';
import { mapPlacement, normalizeTriggers } from '../../utils/misc';

import {
  createInitialPopoverFSMState,
  getPopoverVisualState,
  popoverFSMReducer,
} from './Popover.fsm';
import { PopoverBody } from './PopoverBody';
import { PopoverCloseButton } from './PopoverCloseButton';
import { PopoverHeader } from './PopoverHeader';

import type { PopoverProps } from './Popover.types';
import type { MutableRefObject, ReactElement, Ref } from 'react';

const POPOVER_ARROW_GAP_PX = 8;
const POPOVER_ARROW_WIDTH_PX = 16;
const POPOVER_ARROW_HEIGHT_PX = 8;
const POPOVER_TRANSITION_MS = 150;
const DEFAULT_MAX_WIDTH = 276; // Bootstrap default

function assignNodeToRef<T>(refTarget: Ref<T> | undefined, node: T | null): void {
  if (!refTarget) {
    return;
  }
  if (typeof refTarget === 'function') {
    refTarget(node);
    return;
  }
  if (typeof refTarget === 'object' && refTarget !== null && 'current' in refTarget) {
    (refTarget as MutableRefObject<T | null>).current = node;
  }
}

/**
 * Popover Component
 *
 * A fully accessible popover component that provides richer interactive content
 * compared to tooltips. Uses Floating UI for intelligent positioning.
 *
 * ACCESSIBILITY FEATURES (WCAG 2.2 AA):
 * - role="dialog" on the popover content
 * - aria-labelledby linking to popover header
 * - aria-haspopup="dialog" on trigger
 * - aria-expanded on trigger
 * - ESC key to dismiss
 * - Click outside to dismiss
 * - Optional focus trap for complex content
 *
 * SECURITY FEATURES:
 * - Prop whitelisting (no unrestricted spread)
 * - No dangerouslySetInnerHTML
 * - Explicit event handlers only
 *
 * @example
 * ```tsx
 * // Basic popover
 * <Popover header="Settings" content="Configure your preferences here.">
 *   <button>Open Settings</button>
 * </Popover>
 *
 * // Popover with close button
 * <Popover header="Notification" content="You have new messages" showCloseButton>
 *   <button>Notifications</button>
 * </Popover>
 *
 * // Controlled popover
 * <Popover
 *   header="Info"
 *   content="Detailed information"
 *   isOpen={isOpen}
 *   onOpenChange={setIsOpen}
 * >
 *   <button>Toggle</button>
 * </Popover>
 * ```
 *
 * @see https://getbootstrap.com/docs/5.3/components/popovers/
 */
export const Popover = forwardRef<HTMLElement, PopoverProps>(
  (
    {
      children,
      content,
      header,
      placement = 'top',
      trigger = 'click',
      showCloseButton = false,
      closeButtonLabel = 'Close popover',
      arrow: showArrow = true,
      offset: offsetValue = 8,
      maxWidth = DEFAULT_MAX_WIDTH,
      isOpen: controlledIsOpen,
      onOpenChange,
      defaultOpen = false,
      disabled = false,
      portal = true,
      container,
      trapFocus = false,
      showDelay = 0,
      hideDelay = 0,
      closeOnClickOutside = true,
      closeOnEscape = true,
      className,
      style,
      id,
      'aria-label': ariaLabel,
      'data-testid': dataTestId,
      'data-test': dataTest,
    },
    ref
  ) => {
    // Generate unique IDs
    const generatedId = useId();
    const popoverId = id ?? `popover-${generatedId}`;
    const headerId = `${popoverId}-header`;
    const bodyId = `${popoverId}-body`;

    // Determine if controlled
    const isControlled = controlledIsOpen !== undefined;

    // FSM state for transitions
    const [fsmState, dispatch] = useReducer(popoverFSMReducer, undefined, () =>
      createInitialPopoverFSMState(isControlled ? controlledIsOpen : defaultOpen)
    );

    const [arrowElement, setArrowElement] = useState<SVGSVGElement | null>(null);

    // Normalize triggers
    const triggers = useMemo(() => normalizeTriggers(trigger), [trigger]);
    const hasHover = triggers.includes('hover');
    const hasFocus = triggers.includes('focus');
    const hasClick = triggers.includes('click');

    // Compute isOpen from FSM (for aria attributes on trigger)
    const isOpen = fsmState.visibility === 'open' || fsmState.visibility === 'opening';

    // Build middleware array
    // Note: arrow middleware needs to be included even if showArrow is false
    // to avoid React hooks ordering issues. FloatingArrow handles visibility.
    const middleware = useMemo(
      () => [
        offset(offsetValue + (showArrow ? POPOVER_ARROW_GAP_PX : 0)),
        flip({ fallbackAxisSideDirection: 'start', padding: 8 }),
        shift({ padding: 8 }),
        arrow({ element: arrowElement, padding: 8 }),
      ],
      [offsetValue, showArrow, arrowElement]
    );

    // Floating UI setup
    const {
      refs: floatingRefs,
      floatingStyles,
      context,
      update,
    } = useFloating({
      open: fsmState.shouldRender,
      onOpenChange: (open) => {
        if (disabled) {
          return;
        }

        if (open) {
          dispatch({ type: 'OPEN' });
        } else {
          dispatch({ type: 'CLOSE' });
        }

        onOpenChange?.(open);
      },
      placement: mapPlacement(placement),
      middleware,
      whileElementsMounted: autoUpdate,
    });

    // Interaction hooks
    const hover = useHover(context, {
      enabled: hasHover && !disabled,
      delay: {
        open: showDelay,
        close: hideDelay,
      },
      move: false, // Don't reposition on mouse move within trigger
    });

    const focus = useFocus(context, {
      enabled: hasFocus && !disabled,
    });

    const click = useClick(context, {
      enabled: hasClick && !disabled,
      toggle: true, // Allow clicking again to close
    });

    const dismiss = useDismiss(context, {
      enabled: closeOnClickOutside || closeOnEscape,
      outsidePressEvent: 'mousedown',
      escapeKey: closeOnEscape,
      outsidePress: closeOnClickOutside,
    });

    const role = useRole(context, {
      role: 'dialog',
    });

    // Combine all interactions
    const { getReferenceProps, getFloatingProps } = useInteractions([
      hover,
      focus,
      click,
      dismiss,
      role,
    ]);

    // Transition styles - use opacity only like Tooltip to avoid positioning issues
    const { isMounted, styles: transitionStyles } = useTransitionStyles(context, {
      duration: POPOVER_TRANSITION_MS,
      initial: {
        opacity: 0,
      },
      open: {
        opacity: 1,
      },
      close: {
        opacity: 0,
      },
    });

    // Handle animation end for FSM
    useEffect(() => {
      if (fsmState.visibility === 'opening') {
        const frameId = requestAnimationFrame(() => {
          dispatch({ type: 'ANIMATION_END' });
        });
        return () => cancelAnimationFrame(frameId);
      }

      if (fsmState.visibility === 'closing') {
        const timeoutId = setTimeout(() => {
          dispatch({ type: 'ANIMATION_END' });
        }, POPOVER_TRANSITION_MS);
        return () => clearTimeout(timeoutId);
      }

      return undefined;
    }, [fsmState.visibility]);

    // Sync controlled state with FSM
    useEffect(() => {
      if (!isControlled) {
        return;
      }

      if (controlledIsOpen && fsmState.visibility === 'closed') {
        dispatch({ type: 'OPEN' });
      } else if (
        !controlledIsOpen &&
        (fsmState.visibility === 'open' || fsmState.visibility === 'opening')
      ) {
        dispatch({ type: 'CLOSE' });
      }
    }, [isControlled, controlledIsOpen, fsmState.visibility]);

    // Force a Floating UI re-measure right after paint whenever the popover should render.
    // Using requestAnimationFrame ensures the reference element has a layout box before measuring,
    // preventing the popover from briefly appearing at (0, 0).
    useEffect(() => {
      if (!fsmState.shouldRender) {
        return undefined;
      }

      const frameId = requestAnimationFrame(() => {
        update();
      });

      return () => cancelAnimationFrame(frameId);
    }, [fsmState.shouldRender, update]);

    // Close handler for close button
    const handleClose = useCallback((): void => {
      dispatch({ type: 'CLOSE' });
      onOpenChange?.(false);
    }, [onOpenChange]);

    // Extract child element and its ref for proper merging
    const child = children as ReactElement<{ ref?: React.Ref<HTMLElement> }>;
    const childRef = child?.props?.ref;

    // Merge refs for trigger element via callback to avoid ref reads during render
    const triggerRef = useCallback(
      (node: HTMLElement | null) => {
        floatingRefs.setReference(node);
        assignNodeToRef(childRef, node);
        assignNodeToRef(ref, node);
      },
      [childRef, ref, floatingRefs]
    );

    // Memoize popover class names
    const popoverClassName = useMemo(
      () => cn('popover', 'bs-popover-auto', 'show', className),
      [className]
    );

    // Compute popover styles - properly combine transforms from floating and transition styles
    const popoverStyles = useMemo(() => {
      const { transform: floatingTransform, ...floatingRest } = floatingStyles;
      const { transform: transitionTransform, ...transitionRest } = transitionStyles;

      const combinedTransform = [floatingTransform, transitionTransform].filter(Boolean).join(' ');

      const baseStyles: React.CSSProperties = {
        ...floatingRest,
        ...transitionRest,
        ...style,
        zIndex: 1070, // Bootstrap popover z-index
      };

      if (combinedTransform) {
        baseStyles.transform = combinedTransform;
      }

      if (maxWidth !== undefined) {
        baseStyles.maxWidth = typeof maxWidth === 'number' ? `${maxWidth}px` : maxWidth;
      }

      return baseStyles;
    }, [floatingStyles, transitionStyles, style, maxWidth]);

    const referenceProps = useMemo(
      () =>
        getReferenceProps({
          'aria-haspopup': 'dialog',
          'aria-expanded': isOpen,
          'aria-controls': isOpen ? popoverId : undefined,
        }),
      [getReferenceProps, isOpen, popoverId]
    );

    // Clone trigger element with ref and props
    /* eslint-disable react-hooks/refs */
    const triggerElement = useMemo(() => {
      if (!children) {
        return null;
      }

      return cloneElement(child, {
        ...referenceProps,
        ref: triggerRef,
      });
    }, [children, child, triggerRef, referenceProps]);
    /* eslint-enable react-hooks/refs */

    // Render popover content
    const popoverContent = useMemo(() => {
      if (!isMounted) {
        return null;
      }

      const contentElement = (
        <div
          ref={floatingRefs.setFloating}
          {...getFloatingProps()}
          id={popoverId}
          className={popoverClassName}
          style={popoverStyles}
          role="dialog"
          aria-modal={trapFocus ? 'true' : undefined}
          aria-labelledby={header ? headerId : undefined}
          aria-label={!header ? ariaLabel : undefined}
          aria-describedby={bodyId}
          data-visual-state={getPopoverVisualState(fsmState)}
          data-testid={dataTestId}
          data-test={dataTest}
        >
          {/* Arrow */}
          {showArrow && (
            <FloatingArrow
              ref={setArrowElement}
              context={context}
              width={POPOVER_ARROW_WIDTH_PX}
              height={POPOVER_ARROW_HEIGHT_PX}
              className="popover-arrow"
              fill="var(--bs-popover-bg, #fff)"
              stroke="var(--bs-popover-border-color, rgba(0, 0, 0, 0.175))"
              strokeWidth={1}
            />
          )}

          {/* Close button */}
          {showCloseButton && (
            <PopoverCloseButton onClick={handleClose} aria-label={closeButtonLabel} />
          )}

          {/* Header */}
          {header && <PopoverHeader id={headerId}>{header}</PopoverHeader>}

          {/* Body */}
          <PopoverBody id={bodyId}>{content}</PopoverBody>
        </div>
      );

      // Wrap in focus manager if focus trap is enabled
      if (trapFocus) {
        return (
          <FloatingFocusManager context={context} modal>
            {contentElement}
          </FloatingFocusManager>
        );
      }

      return contentElement;
    }, [
      isMounted,
      popoverId,
      popoverClassName,
      popoverStyles,
      trapFocus,
      header,
      headerId,
      ariaLabel,
      bodyId,
      fsmState,
      dataTestId,
      dataTest,
      getFloatingProps,
      showArrow,
      context,
      showCloseButton,
      handleClose,
      closeButtonLabel,
      content,
      floatingRefs.setFloating,
    ]);

    return (
      <>
        {triggerElement}
        {portal ? (
          <FloatingPortal root={container}>{popoverContent}</FloatingPortal>
        ) : (
          popoverContent
        )}
      </>
    );
  }
);

Popover.displayName = 'Popover';

import type { SafeHTMLAttributes } from '../../types';
import type { ReactElement, ReactNode } from 'react';

/**
 * Popover placement options
 * Maps to Floating UI placement values
 */
export type PopoverPlacement =
  | 'top'
  | 'top-start'
  | 'top-end'
  | 'bottom'
  | 'bottom-start'
  | 'bottom-end'
  | 'left'
  | 'left-start'
  | 'left-end'
  | 'right'
  | 'right-start'
  | 'right-end';

/**
 * Popover trigger types
 */
export type PopoverTrigger = 'click' | 'hover' | 'focus';

/**
 * Safe HTML attributes that can be spread onto popover elements
 * SECURITY: This whitelist prevents injection of dangerous attributes or event handlers
 * @see {@link SafeHTMLAttributes}
 */
export type SafePopoverHTMLAttributes = SafeHTMLAttributes<HTMLDivElement>;

/**
 * PopoverHeader component props
 *
 * @example
 * ```tsx
 * <PopoverHeader>Settings</PopoverHeader>
 * ```
 */
export interface PopoverHeaderProps extends SafePopoverHTMLAttributes {
  /**
   * Header content
   */
  children: ReactNode;
}

/**
 * PopoverBody component props
 *
 * @example
 * ```tsx
 * <PopoverBody>
 *   <p>Popover content goes here</p>
 * </PopoverBody>
 * ```
 */
export interface PopoverBodyProps extends SafePopoverHTMLAttributes {
  /**
   * Body content
   */
  children: ReactNode;
}

/**
 * PopoverCloseButton component props
 *
 * @example
 * ```tsx
 * <PopoverCloseButton onClick={handleClose} />
 * ```
 */
export interface PopoverCloseButtonProps extends SafePopoverHTMLAttributes {
  /**
   * Click handler to close the popover
   */
  onClick: () => void;

  /**
   * Accessible label for the close button
   * @default 'Close'
   */
  'aria-label'?: string;
}

/**
 * Popover component props
 *
 * A fully accessible popover component that provides richer interactive content
 * compared to tooltips. Uses Floating UI for intelligent positioning.
 *
 * ACCESSIBILITY FEATURES (WCAG 2.2 AA):
 * - role="dialog" on the popover content
 * - aria-labelledby linking to popover header
 * - aria-haspopup="dialog" on trigger
 * - aria-expanded on trigger
 * - ESC key to dismiss
 * - Click outside to dismiss
 * - Optional focus trap for complex content
 *
 * SECURITY FEATURES:
 * - Prop whitelisting (no unrestricted spread)
 * - No dangerouslySetInnerHTML
 * - Explicit event handlers only
 *
 * @example
 * ```tsx
 * // Basic popover
 * <Popover
 *   header="Settings"
 *   content={<p>Configure your preferences here.</p>}
 * >
 *   <button>Open Settings</button>
 * </Popover>
 *
 * // Popover with custom placement
 * <Popover
 *   header="Help"
 *   content="Click here for more info"
 *   placement="right"
 * >
 *   <button>?</button>
 * </Popover>
 *
 * // Popover with close button
 * <Popover
 *   header="Notification"
 *   content="You have new messages"
 *   showCloseButton
 * >
 *   <button>Notifications</button>
 * </Popover>
 * ```
 */
export interface PopoverProps extends SafePopoverHTMLAttributes {
  /**
   * The element that triggers the popover.
   * Must be a single React element that accepts ref forwarding.
   */
  children: ReactElement;

  /**
   * Popover content to display in the body.
   * Can be text or any React node.
   */
  content: ReactNode;

  /**
   * Optional header content.
   * Provides the aria-labelledby target for accessibility.
   */
  header?: ReactNode;

  /**
   * Placement of the popover relative to the trigger element.
   * Uses Floating UI for positioning with auto-flip on viewport edges.
   * @default 'top'
   */
  placement?: PopoverPlacement;

  /**
   * How to trigger the popover visibility.
   * - 'click': Show/hide on click (default)
   * - 'hover': Show on mouse hover
   * - 'focus': Show on keyboard focus
   *
   * Note: Multiple triggers can be combined using an array.
   * @default 'click'
   */
  trigger?: PopoverTrigger | PopoverTrigger[];

  /**
   * Whether to show the close button in the header.
   * @default false
   */
  showCloseButton?: boolean;

  /**
   * Custom close button aria-label.
   * @default 'Close popover'
   */
  closeButtonLabel?: string;

  /**
   * Whether to show the arrow pointer.
   * @default true
   */
  arrow?: boolean;

  /**
   * Offset from the trigger element in pixels.
   * @default 8
   */
  offset?: number;

  /**
   * Maximum width of the popover content.
   * @default 276 (Bootstrap default)
   */
  maxWidth?: number | string;

  /**
   * Controlled open state.
   * If provided, popover becomes controlled.
   */
  isOpen?: boolean;

  /**
   * Callback when open state changes.
   * Called when popover opens or closes.
   */
  onOpenChange?: (isOpen: boolean) => void;

  /**
   * Default open state for uncontrolled mode.
   * @default false
   */
  defaultOpen?: boolean;

  /**
   * Whether the popover is disabled.
   * When disabled, the popover will not show.
   * @default false
   */
  disabled?: boolean;

  /**
   * Whether to render the popover in a portal.
   * @default true
   */
  portal?: boolean;

  /**
   * Container element for the portal.
   * @default document.body
   */
  container?: HTMLElement | null;

  /**
   * Whether to trap focus within the popover when open.
   * Recommended for popovers with interactive content.
   * @default false
   */
  trapFocus?: boolean;

  /**
   * Delay in milliseconds before showing (for hover trigger).
   * @default 0
   */
  showDelay?: number;

  /**
   * Delay in milliseconds before hiding (for hover trigger).
   * @default 0
   */
  hideDelay?: number;

  /**
   * Whether clicking outside closes the popover.
   * @default true
   */
  closeOnClickOutside?: boolean;

  /**
   * Whether pressing ESC closes the popover.
   * @default true
   */
  closeOnEscape?: boolean;

  /**
   * ARIA label for the popover.
   * Used when header is not provided or is not a string.
   */
  'aria-label'?: string;
}

/**
 * Popover context value for sharing state between components.
 *
 * @experimental Exported for future compound-component API. Not yet consumed internally.
 */
export interface PopoverContextValue {
  /** Whether the popover is currently visible */
  isOpen: boolean;
  /** Open the popover */
  open: () => void;
  /** Close the popover */
  close: () => void;
  /** Toggle the popover */
  toggle: () => void;
  /** Whether the popover is disabled */
  disabled: boolean;
  /** Popover ID for aria attributes */
  popoverId: string;
  /** Header ID for aria-labelledby */
  headerId: string;
  /** Body ID for aria-describedby */
  bodyId: string;
  /** Current placement of the popover */
  placement: PopoverPlacement;
}

/**
 * Internal FSM state for popover visibility
 */
export interface PopoverFSMState {
  /** Current visibility state */
  visibility: 'closed' | 'opening' | 'open' | 'closing';
  /** Whether the popover should be rendered in DOM */
  shouldRender: boolean;
}

/**
 * FSM events for popover state transitions
 */
export type PopoverFSMEvent = { type: 'OPEN' } | { type: 'CLOSE' } | { type: 'ANIMATION_END' };

/**
 * Visual state for data attribute (for CSS styling and testing)
 */
export type PopoverVisualState = 'hidden' | 'showing' | 'visible' | 'hiding';

import { forwardRef, useMemo } from 'react';

import { cn } from '../../utils';

import type { PopoverBodyProps } from './Popover.types';

/**
 * PopoverBody Component
 *
 * Body section of the Popover containing the main content.
 *
 * ACCESSIBILITY:
 * - Provides aria-describedby target for the popover dialog
 *
 * SECURITY: No unrestricted prop spreading. Only whitelisted attributes are passed to DOM.
 *
 * @example
 * ```tsx
 * <PopoverBody>
 *   <p>Configure your preferences here.</p>
 * </PopoverBody>
 * ```
 *
 * @see https://getbootstrap.com/docs/5.3/components/popovers/
 */
export const PopoverBody = forwardRef<HTMLDivElement, PopoverBodyProps>(
  ({ children, className, style, id, 'data-testid': dataTestId, 'data-test': dataTest }, ref) => {
    // Memoize class name computation
    const bodyClassName = useMemo(() => cn('popover-body', className), [className]);

    return (
      <div
